/**
* simplify a string to insert it into an URL
*
* @param string
* @return string
*/
function str2url($str)
{
$raw = $str;

$str = remove_accents($str);
$str = preg_replace('/[^a-z0-9_\s\'\:\/\[\],-]/','',strtolower($str));
$str = preg_replace('/[\s\'\:\/\[\],-]+/',' ',trim($str));
$res = str_replace(' ','_',$str);

if (empty($res))
{
$res = str_replace(' ','_', $raw);
}

return $res;
}



