$type
));
while ($lrow = sqlFetchArray($lres)) {
if ($tmp) {
$tmp .= '; ';
}

$tmp .= $lrow['title'];
if ($lrow['comments']) {
$tmp .= ' (' . $lrow['comments'] . ')';
}
}

return $tmp;
}


