if safe_page_name != page_name:
app.logger.error(f"Invalid page name '{page_name}' rejected")
return

filename = os.path.join(cfg.wiki_directory, safe_page_name + '.md')
# Ensure the resolved path is within the wiki directory
real_path = os.path.realpath(filename)
wiki_real = os.path.realpath(cfg.wiki_directory)
if not real_path.startswith(wiki_real + os.sep) and real_path != wiki_real:
app.logger.error(f"Path traversal detected for '{page_name}'")
return

dirname = os.path.dirname(filename)
if not os.path.exists(dirname):
os.makedirs(dirname)
with open(filename, 'w') as f:
