@router.post("/knowledge/{space_name}/document/upload")
async def document_upload(
space_name: str,
doc_name: str = Form(...),
doc_type: str = Form(...),
doc_file: UploadFile = File(...),
):
print(f"/document/upload params: {space_name}")
try:
if doc_file:
# Validate space_name to prevent path traversal
if ".." in space_name or "/" in space_name or "\\" in space_name:
return Result.failed(code="E000X", msg="Invalid space name")

# Validate filename to prevent path traversal
filename = doc_file.filename
if filename:
# Remove any path components from filename
filename = os.path.basename(filename)
if not filename:
return Result.failed(code="E000X", msg="Invalid filename")
else:
return Result.failed(code="E000X", msg="Filename is required")

upload_dir = os.path.join(KNOWLEDGE_UPLOAD_ROOT_PATH, space_name)
if not os.path.exists(upload_dir):
os.makedirs(upload_dir)
# We can not move temp file in windows system when we open file in context of `with`
tmp_fd, tmp_path = tempfile.mkstemp(dir=upload_dir)
with os.fdopen(tmp_fd, "wb") as tmp:
tmp.write(await doc_file.read())

# Use the sanitized filename
dest_path = os.path.join(upload_dir, filename)
shutil.move(tmp_path, dest_path)

request = KnowledgeDocumentRequest()
request.doc_name = doc_name
request.doc_type = doc_type
request.content = dest_path
space_res = knowledge_service_handler.get_knowledge_space(
KnowledgeSpaceRequest(name=space_name)
)
if len(space_res) == 0:
# create default space
if "default" != space_name:
raise Exception(f"you have not create your knowledge space.")
knowledge_service_handler.create_knowledge_space(
KnowledgeSpaceRequest(
name=space_name,
desc="first db-gpt rag application",
owner="dbgpt",
)
)
return Result.succ(
knowledge_service_handler.create_knowledge_document(
space=space_name, request=request
)
)
return Result.failed(code="E000X", msg=f"doc_file is None")
except Exception as e:
return Result.failed(code="E000X", msg=f"document add error {e}")


