doc_type: str = Form(...),
doc_file: UploadFile = File(...),
):
print(f"/document/upload params: {space_name}")
try:
if doc_file:
# Validate space_name to prevent path traversal
if ".." in space_name or "/" in space_name or "\\" in space_name:
return Result.failed(code="E000X", msg=f"Invalid space name")

# Validate filename to prevent path traversal
filename = doc_file.filename
if filename is None:
return Result.failed(code="E000X", msg=f"Invalid filename")

# Sanitize filename - remove any path components
filename = os.path.basename(filename)
if not filename:
return Result.failed(code="E000X", msg=f"Invalid filename")

upload_dir = os.path.join(KNOWLEDGE_UPLOAD_ROOT_PATH, space_name)
if not os.path.exists(upload_dir):
os.makedirs(upload_dir)

# Create temporary file in the upload directory
tmp_fd, tmp_path = tempfile.mkstemp(dir=upload_dir)
with os.fdopen(tmp_fd, "wb") as tmp:
tmp.write(await doc_file.read())

# Move to final destination with sanitized filename
final_path = os.path.join(upload_dir, filename)
shutil.move(tmp_path, final_path)

request = KnowledgeDocumentRequest()
request.doc_name = doc_name
request.doc_type = doc_type
request.content = final_path
space_res = knowledge_space_service.get_knowledge_space(
KnowledgeSpaceRequest(name=space_name)
)
if len(space_res) == 0:
# create default space
if "default" != space_name:
raise Exception(f"you have not create your knowledge space.")
knowledge_space_service.create_knowledge_space(
KnowledgeSpaceRequest(
name=space_name,
desc="first db-gpt rag application",
owner="dbgpt",
)
)
return Result.succ(
knowledge_space_service.create_knowledge_document(
space=space_name, request=request
)
)
