real_file = os.path.realpath(filename)
if not real_file.startswith(real_wiki + os.sep) and real_file != real_wiki:
app.logger.error(f"Path traversal detected: '{filename}'")
return

dirname = os.path.dirname(filename)
if not os.path.exists(dirname):
os.makedirs(dirname)
