def sanitize_path(user_input):
"""Sanitize user input to prevent path traversal."""
# Remove any path traversal attempts
sanitized = os.path.normpath(user_input).lstrip('/')
# Prevent going above the base directory
if sanitized.startswith('..') or '/..' in sanitized:
return None
return sanitized

def save(page_name):
"""
Function that saves a *.md page.
:param page_name: name of the page
"""
content = request.form['CT']
app.logger.info(f"Saving >>> '{page_name}' ...")

try:
# Sanitize page_name to prevent path traversal
safe_page_name = sanitize_path(page_name)
if safe_page_name is None:
app.logger.error(f"Invalid page name: '{page_name}'")
return

filename = os.path.join(cfg.wiki_directory, safe_page_name + '.md')
# Ensure the resolved path is within the wiki directory
real_path = os.path.realpath(filename)
wiki_dir = os.path.realpath(cfg.wiki_directory)
if not real_path.startswith(wiki_dir + os.sep) and real_path != wiki_dir:
app.logger.error(f"Path traversal detected: '{filename}'")
return

dirname = os.path.dirname(filename)
if not os.path.exists(dirname):
os.makedirs(dirname)
with open(filename, 'w') as f:
f.write(content)
except Exception as e:
app.logger.error(f"Error while saving '{page_name}' >>> {str(e)}")


